grid = [[0]*8 for _ in range(8)]
# Preserve the two 2x2 blocks
for r0,c0 in [(1,3),(5,1)]:
    for r in range(r0,r0+2):
        for c in range(c0,c0+2): grid[r][c]=2
# Outward diagonal rays from each block's four corner markers.
# (row, col, dr, dc, input color)
markers=[(0,2,-1,-1,3),(0,5,-1,1,8),(3,2,1,-1,7),(3,5,1,1,6),
         (4,0,-1,-1,7),(4,3,-1,1,6),(7,0,1,-1,8),(7,3,1,1,3)]
perm={3:8,8:7,7:6,6:3}
for r,c,dr,dc,color in markers:
    while 0<=r<8 and 0<=c<8:
        grid[r][c]=perm[color]
        r+=dr;c+=dc
print(grid)
